                        if 0 <= nx < grid_size and 0 <= ny < grid_size and (nx, ny) not in blue and (nx, ny) not in red:
                            neighbors.add((nx, ny))
                if neighbors:
                    best_natasha_move = list(neighbors)[0]
                else:
                    for x in range(grid_size):
                        for y in range(grid_size):
                            if (x, y) not in blue and (x, y) not in red:
                                best_natasha_move = (x, y)
                                break
                        if best_natasha_move: break
                if best_natasha_move:
                    red.add(best_natasha_move)
                else:
                    break

    if not blue: return 0
    visited = set()
    max_comp = 0
    for b in blue:
        if b not in visited:
            comp = 0
            q = collections.deque([b])
            visited.add(b)
            while q:
                curr = q.popleft()
                comp += 1
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = curr[0] + dx, curr[1] + dy
                    if (nx, ny) in blue and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        q.append((nx, ny))
            max_comp = max(max_comp, comp)
    return max_comp

